def compute(vars):
    gross_profit = vars["Gross Profit"]
    net_sales = vars["Net Sales"]

    cost_of_sales = -gross_profit + net_sales

    return {
        "value": cost_of_sales,
        "trace": {
            "Gross Profit": gross_profit,
            "Net Sales": net_sales,
            "output_meta": {
                "currency": "dollars",
                "scale": "millions",
                "unit": None
            }
        }
    }
